CustomField.formula:
IF ( ( TEXT(BizRegion__c) = 'LK_KR' || TEXT(BizRegion__c) = 'LK_A&G' ) && TEXT(Currency__c) = 'KRW' , BrokerageAmt__c  *  1,
    IF ( TEXT(BizRegion__c) = 'LK_Re' && TEXT(Currency__c) = 'USD' , BrokerageAmt__c  *  1,
        IF ( TEXT(BizRegion__c) = 'LK_VN' && TEXT(Currency__c) = 'VDN' , BrokerageAmt__c  *  1,
           IF ( NOT(ISBLANK(ExchangeRatePolicy__c)), BrokerageAmt__c * ExchangeRatePolicy__c, BrokerageAmt__c  *  ExchangeRate__c )
           )
        )
    )
